/** Runs an operation under its driver lock, persisting every transition through the store. */
/** Best-effort Linux boot identity. A goal/operation active in a different boot was left by an earlier process. */
export function currentBootId(): string | undefined {
  try { return fs.readFileSync("/proc/sys/kernel/random/boot_id", "utf8").trim() || undefined; }
  catch { return undefined; }
}

function processAlive(pid: number): boolean {
  try { process.kill(pid, 0); return true; }
  catch (err: any) { return err?.code === "EPERM"; }
}

function pauseForStaleDriver(state: DurableOperationState, bootId: string | undefined, store: OperationStore): string | undefined {
  if (!["RUNNING", "WAITING"].includes(state.status)) return undefined;
  // A newly persisted plan is RUNNING before its first assignment, but has no prior driver identity. There is no
  // interrupted execution to reconcile yet, so let its first driver start it instead of treating the plan as stale.
  if (state.status === "RUNNING" && state.units.every((unit) =>
    unit.status === "WAITING_ON_DEPENDENCY" && unit.runs === 0 && unit.agentTaskId === undefined
  )) return undefined;
  const host = os.hostname();
  const liveLock = store.activeLock(state.id);
  if (liveLock) return undefined; // another live driver owns it; caller should not drive concurrently

  const reasons: string[] = [];
  if (bootId && state.activeBootId && state.activeBootId !== bootId) {
    reasons.push(`earlier host boot (${state.activeBootId.slice(0, 12)})`);
  }
  if (state.activePid !== undefined && state.activeHost === host && !processAlive(state.activePid)) {
    reasons.push(`earlier process (pid ${state.activePid}) is no longer running`);
  }
  // Missing driver identity on an active operation written before this metadata existed is treated as stale.
  if (reasons.length === 0 && state.activePid === undefined && state.activeBootId === undefined) {
    reasons.push("an earlier process left it active without driver identity metadata");
  }
  if (reasons.length === 0) return undefined;

  const reason = `Paused on resume: this operation was left active by ${reasons.join("; ")}. It was not cleanly paused before this process started. Resume it explicitly after inspecting its state.`;
  state.status = "PAUSED";
  state.pauseReason = reason;
  delete state.wait;
  delete state.blocked;
  state.updatedAt = new Date().toISOString();
  state.events.push({ type: "OPERATION_PAUSED", at: state.updatedAt, message: reason, detail: { reason: "stale_driver", previousBootId: state.activeBootId, previousPid: state.activePid, previousHost: state.activeHost } });
  if (state.events.length > 300) state.events.splice(0, state.events.length - 300);
  return reason;
}

export async function driveOperation(state: DurableOperationState, opts: DriveOptions): Promise<DurableOperationState> {
  const { store, signal, entry, prepare, resumeAfterDecision, ...runnerOpts } = opts;
  const release = store.acquire(state.id);
  try {
    if (entry === "new") {
      if (store.has(state.id)) throw new OperationExistsError(state.id);
    } else if (entry === "existing") {
      state = store.load(state.id);
    }
    const bootId = currentBootId();
    if (entry === "existing") {
      // `operation decide` records the operator's choice, then resumes under a new driver lock in this same process.
      // Refresh the identity for that handoff so the process that presented the decision is not mistaken for a second
      // crash. If this process dies during resumed work, its identity is stale on the next load.
      if (resumeAfterDecision && state.status !== "COMPLETE" && state.status !== "CANCELLED") {
        if (bootId) state.activeBootId = bootId;
        state.activePid = process.pid;
        state.activeHost = os.hostname();
      }
      pauseForStaleDriver(state, bootId, store);
    }
    prepare?.(state);
    if (state.status === "PAUSED" && state.pauseReason?.startsWith("Paused on resume:")) {
      store.save(state);
      return state;
    }
    if (state.status !== "COMPLETE" && state.status !== "CANCELLED") {
      if (bootId) state.activeBootId = bootId;
      state.activePid = process.pid;
      state.activeHost = os.hostname();
    } else {
      delete (state as any).activeBootId;
      delete (state as any).activePid;
      delete (state as any).activeHost;
    }
    const result = await new OperationRunner(state, { ...runnerOpts, store, persist: (s) => store.save(s) }).run(signal);
    if (result.status === "COMPLETE" || result.status === "CANCELLED" || result.status === "PAUSED") {
      delete (result as any).activeBootId;
      delete (result as any).activePid;
      delete (result as any).activeHost;
      store.save(result);
    }
    return result;
  } finally {
    release();
  }
}

/**
 * Applies an operator decision under the driver lock: validated against the persisted decision (DecisionRejected
 * otherwise), recorded on the unit, persisted. The next run re-evaluates the operation from there.
 */
      return { id: fresh.id, status: state.status, operation: fresh, usage: this.usage(fresh), ...(ledger ? { ledger } : {}), ...(state.reason ? { reason: state.reason } : {}) };
    } finally {
      release();
    }
  }

  async start(objective: string): Promise<GoalResult> {
    const text = objective.trim();
    if (!text) throw new Error("goal objective cannot be empty");
    if (text.length > 24_000) throw new Error("goal objective exceeds 24,000 characters");
    const id = `${GOAL_ID_PREFIX}${randomUUID()}`;
    const team = new TeamOrchestrator(this.config, {
      id,
      independentReview: true,
      resources: this.options.resources,
      store: this.store,
      executor: this.executor,
      signal: this.options.signal,
      onEvent: this.options.onEvent,
      maxInProcessWaitMs: this.options.maxInProcessWaitMs,
    });
    const operation = team.plan("full", text);
    const bootId = currentBootId();
    if (bootId) operation.activeBootId = bootId;
    operation.activePid = process.pid;
    operation.activeHost = os.hostname();
    const reviewer = operation.units.find((unit) => unit.id === "review");
    if (!reviewer || !operation.units.some((unit) => unit.id === "verify")) throw new Error("goal workflow is missing its verification or independent review unit");
    // Independent acceptance review must inspect the post-verification candidate, including any test changes.
    reviewer.dependsOn = ["verify"];
    this.store.save(operation);
    this.persistInitialLedger(id, text);
    const result = await driveOperation(operation, {
      store: this.store,
      executor: this.executor,
      workspace: this.config.workspace,
      signal: this.options.signal,
      ...(this.options.onEvent ? { onEvent: this.options.onEvent } : {}),
      ...(this.options.maxInProcessWaitMs !== undefined ? { maxInProcessWaitMs: this.options.maxInProcessWaitMs } : {}),
      entry: "existing",
    });
    return this.result(result);
  }

  async resume(id?: string): Promise<GoalResult> {
    const selected = this.resolveTarget(id);
    if (selected.status === "CANCELLED") throw new Error(`goal ${selected.id} was cancelled and cannot be resumed`);
    const result = await driveOperation(selected, {
      store: this.store,
      executor: this.executor,
      workspace: this.config.workspace,
      signal: this.options.signal,
      ...(this.options.onEvent ? { onEvent: this.options.onEvent } : {}),
      ...(this.options.maxInProcessWaitMs !== undefined ? { maxInProcessWaitMs: this.options.maxInProcessWaitMs } : {}),
      entry: "existing",
      prepare: (fresh) => {
        if (fresh.status === "PAUSED") {
          fresh.status = fresh.wait ? "WAITING" : "RUNNING";
          delete fresh.pauseReason;
        }
      },
    });
    return this.result(result);
  }

  async cancel(id?: string): Promise<GoalResult> {
    const selected = this.resolveTarget(id);
    const release = this.store.acquire(selected.id);
    let result: DurableOperationState;
    try {
      const fresh = this.store.load(selected.id);
      if (fresh.status === "COMPLETE" || fresh.status === "CANCELLED") result = fresh;
      else if (fresh.units.some((unit) => unit.status === "RUNNING")) {
        throw new Error(`goal ${fresh.id} has an unsettled work unit; resume it first so Nexus can reconcile unknown effects before cancellation`);
      } else {
        result = await new OperationRunner(fresh, {
          executor: this.executor,
          workspace: this.config.workspace,
          store: this.store,
          persist: (state) => this.store.save(state),
          ...(this.options.onEvent ? { onEvent: this.options.onEvent } : {}),
        }).run(AbortSignal.abort());
      }
    } finally { release(); }
    return this.result(result);
  }

  async pause(id?: string): Promise<GoalResult> {
    const selected = this.resolveTarget(id);
    const release = this.store.acquire(selected.id);
    let operation: DurableOperationState;
    let unchanged = false;
    try {
      operation = this.store.load(selected.id);
      const stale = staleDriverReason(operation);
      if (stale) {
        operation.status = "PAUSED";
        operation.pauseReason = stale;
        delete operation.wait;
        delete operation.blocked;
        this.store.save(operation);
        unchanged = true;
      } else if (["COMPLETE", "CANCELLED", "PAUSED"].includes(operation.status)) unchanged = true;
      else if (operation.units.some((unit) => unit.status === "RUNNING")) {
        throw new Error(`goal ${operation.id} is executing a work unit; let it settle, then pause at the next safe boundary`);
      } else {
        const runner = new OperationRunner(operation, {
          executor: this.executor,
          workspace: this.config.workspace,
          store: this.store,
          persist: (state) => this.store.save(state),
          ...(this.options.onEvent ? { onEvent: this.options.onEvent } : {}),
        });
        runner.scheduler.pause();
        operation.pauseReason = "Paused by operator at a safe boundary.";
        this.store.save(operation);
      }
    } finally { release(); }
    return this.result(unchanged ? selected : operation!);
  }

  results(id?: string): GoalResult {
    return this.result(this.resolveTarget(id));
  }

  updateDescoping(action: "descope" | "accept", requirementId: string, reason?: string, id?: string): ObjectiveLedger {
    const operation = this.resolveTarget(id);
    const release = this.store.acquire(operation.id);
    try {
      const fresh = this.store.load(operation.id);
      if (fresh.status === "RUNNING" || fresh.units.some((unit) => unit.status === "RUNNING")) {
        throw new Error("pause the goal before changing its requirement scope");
      }
      const state = this.store.manager.loadTaskState(operation.id, this.config.workspace);
      const ledger = state.objective;
      if (!ledger) throw new Error("goal objective ledger is missing or corrupt");
      if (action === "descope") {
        const note = reason?.trim();
        if (!note) throw new Error("operator descoping requires a reason");
        const changed = applyRequirementUpdates(ledger, [{ id: requirementId, status: "descoped", note }]);
        if (!changed.ok) throw new Error(changed.errors.join("; "));
      } else {
        const accepted = acceptDescoping(ledger, [requirementId]);
        if (!accepted.accepted.includes(requirementId)) throw new Error(`requirement ${requirementId} is not proposed as descoped`);
      }
      this.store.manager.saveTaskState(state);
      return ledger;
    } finally { release(); }
  }
}

