        const send = () => {
          if (res.writableEnded || res.destroyed) return;
          res.statusCode = answer.status;
          res.setHeader("content-type", "application/json");
          res.end(typeof answer.body === "string" ? answer.body : JSON.stringify(answer.body));
        };
        if (answer.delayMs) setTimeout(send, answer.delayMs); else send();
      });
      return;
    }
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      let body: any = {};
      try { body = JSON.parse(raw); } catch {}
      // Count only chat-completion requests as "requests" for test assertions; probes/models/tokenize are tracked separately.
      const isChat = req.url?.endsWith("/chat/completions") || Array.isArray(body?.messages);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content);
  }
  execSync("git init -q && git config user.name t && git config user.email t@t.invalid && git add . && git commit -qm base", { cwd: repo, stdio: "ignore" });
  return repo;
}

